      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder).toEqual([
        'beforeSession',
        'beforeUserInput',
        'afterUserInput',
        'beforeModelResponse',
        'afterModelResponse',
        'afterSession',
      ]);
    });

    it('error path calls onError then afterSession', async () => {
      const callOrder: string[] = [];

      const hooks = recordingHooks(callOrder, [
        'beforeSession',
        'beforeUserInput',
        'afterUserInput',
        'beforeModelResponse',
        'afterModelResponse',
        'onError',
        'afterSession',
